<script setup lang="ts">
import { useUnsavedChanges } from './useUnsavedChanges';
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { ElButton, ElCard } from 'element-plus';
import type { Context, Role, Scenario } from './dashboard';
import { memberPermissions, tenants, type Member, type MemberInput, type Quota, type QuotaResource, type TenantInput, type TenantQuery, type TenantSummary, type UsageRow } from './tenants';
import './dashboard.css';
import './tenants.css';

type Tab = 'overview' | 'members' | 'roles' | 'quotas' | 'products' | 'devices';
type Editor = 'tenant' | 'member' | 'quota' | null;
const names: Record<string, string> = { all: '全部租户', ten_202609_001: '华东智联', ten_202609_002: '全球能源' };
const statusNames = { active: '正常', suspended: '已停用' };
const planNames = { standard: '标准版', professional: '专业版', enterprise: '企业版' };
const roleNames = { tenantAdmin: '租户管理员', operator: '运维工程师', viewer: '数据观察员' };
const resourceNames: Record<QuotaResource, string> = { devices: '设备', products: '产品', messages: '消息量', storageMb: '存储（MiB）', otaConcurrent: 'OTA 并发' };
const quotaResourceRoute: Partial<Record<QuotaResource, string>> = { devices: '/devices', storageMb: '/firmware', otaConcurrent: '/firmware?tab=ota' };
const quotaResourceHref = (resource: QuotaResource, tenantId: string) => { const route = quotaResourceRoute[resource]; return route ? `${route}${route.includes('?') ? '&' : '?'}tenant=${encodeURIComponent(tenantId)}` : null; };
const resources = Object.keys(resourceNames) as QuotaResource[];
const tabs: Record<Tab, string> = { overview: '概览', members: '成员', roles: '角色', quotas: '配额', products: '产品', devices: '设备' };
const healthNames = { normal: '正常', warning: '预警', exceeded: '超限' };
const baseQuery = (tenantId: string): TenantQuery => ({ tenantId, seed: 42, page: 1, pageSize: 10 });
const emptyQuota = (): Quota => ({ devices: { limit: 100, warningAt: 80 }, products: { limit: 20, warningAt: 80 }, messages: { limit: 10_000, warningAt: 80 }, storageMb: { limit: 512, warningAt: 80 }, otaConcurrent: { limit: 5, warningAt: 80 } });
const emptyTenant = (): TenantInput => ({ name: '', key: '', status: 'active', plan: 'standard', contact: '', email: '', description: '', quota: emptyQuota() });
const emptyMember = (): MemberInput => ({ name: '', email: '', role: 'viewer', status: 'active' });
const persistedTenant = () => { const id = localStorage.getItem('iot-atlas-current-tenant-v1'); return id && (id === 'all' || /^ten_202609_\d+$/.test(id)) ? id : 'all'; };
const plain = <T>(value: T): T => JSON.parse(JSON.stringify(value)) as T;
const role = ref<Role>('platformAdmin'), scenario = ref<Scenario>('normal');
const themeChoice = ref(localStorage.getItem('iot-atlas-theme') || 'dark');
const media = matchMedia('(prefers-color-scheme: dark)'), systemDark = ref(media.matches);
const dark = computed(() => themeChoice.value === 'dark' || themeChoice.value === 'system' && systemDark.value);
const currentTenant = ref(persistedTenant());
const draft = ref<TenantQuery>(baseQuery(currentTenant.value)), query = ref<TenantQuery>(baseQuery(currentTenant.value));
const rows = ref<TenantSummary[]>([]), total = ref(0), choices = ref<TenantSummary[]>([]);
const selected = ref<(TenantSummary & { members: Member[] }) | null>(null), tab = ref<Tab>('overview');
const editor = ref<Editor>(null), editedMember = ref<Member | null>(null), editingTenantId = ref<string | null>(null);
const tenantDraft = ref<TenantInput>(emptyTenant()), memberDraft = ref<MemberInput>(emptyMember()), quotaDraft = ref<Quota>(emptyQuota());
const quotaPreview = ref<{ usage: UsageRow[]; blocked: UsageRow[] } | null>(null);
const message = ref(''), revision = ref(0), dirty = ref(false);
const canWrite = computed(() => role.value === 'platformAdmin');
const selectedHealth = computed(() => selected.value?.health ?? 'normal');
const context = (): Context => ({ actorId: 'usr_202609_001', role: role.value, tenantId: role.value === 'platformAdmin' ? 'all' : 'ten_202609_001', seed: 42, scenario: scenario.value });
const mediaChanged = () => { systemDark.value = media.matches; };
media.addEventListener('change', mediaChanged);
onBeforeUnmount(() => media.removeEventListener('change', mediaChanged));
watch(dark, value => { document.documentElement.dataset.theme = value ? 'dark' : 'light'; localStorage.setItem('iot-atlas-theme', themeChoice.value); }, { immediate: true });
watch([query, role, scenario, revision], async () => { const result = await tenants.list(context(), plain(query.value)); if ('error' in result) { message.value = result.error.message; rows.value = []; total.value = 0; } else { rows.value = result.data.items; total.value = result.data.total; } }, { immediate: true });
watch([role, scenario, revision], async () => { if (role.value !== 'platformAdmin') return; const result = await tenants.list(context(), baseQuery('all')); if ('data' in result) choices.value = result.data.items; }, { immediate: true });
function checkDiscard() { return !dirty.value || window.confirm('当前编辑尚未保存，放弃修改吗？'); }
function closeEditor() { if (!checkDiscard()) return; editor.value = null; dirty.value = false; quotaPreview.value = null; }
async function open(id: string, nextTab: Tab = 'overview', preserveMessage = false, afterSave = false) { if (!afterSave && !checkDiscard()) return; editor.value = null; dirty.value = false; const result = await tenants.get(context(), id); if ('error' in result) { message.value = result.error.message; return; } selected.value = result.data; tab.value = nextTab; if (!preserveMessage) message.value = ''; }
function switchTenant(id: string) { if (!checkDiscard()) return; const next = role.value === 'platformAdmin' ? id : 'ten_202609_001'; localStorage.setItem('iot-atlas-current-tenant-v1', next); currentTenant.value = next; draft.value = baseQuery(next); query.value = baseQuery(next); selected.value = null; editor.value = null; dirty.value = false; message.value = `已切换当前租户：${names[next] ?? next}`; }
function changeRole(next: Role) { if (!checkDiscard()) return; role.value = next; const id = next === 'platformAdmin' ? persistedTenant() : 'ten_202609_001'; currentTenant.value = id; draft.value = baseQuery(id); query.value = baseQuery(id); selected.value = null; editor.value = null; dirty.value = false; message.value = ''; }
function startTenant(mode: 'new' | 'edit') { if (mode === 'edit' && !selected.value) return; editingTenantId.value = mode === 'edit' ? selected.value!.id : null; tenantDraft.value = mode === 'new' ? emptyTenant() : plain(selected.value!); editor.value = 'tenant'; dirty.value = false; message.value = ''; }
async function saveTenant() { const result = await tenants.save(context(), plain(tenantDraft.value), editingTenantId.value ?? undefined, editingTenantId.value ? selected.value?.revision : undefined); if ('error' in result) { message.value = result.error.message; return; } editor.value = null; dirty.value = false; revision.value++; message.value = `租户 ${result.data.name} 已保存`; await open(result.data.id, 'overview', true, true); }
function startMember(member: Member | null) { editedMember.value = member; memberDraft.value = member ? { name: member.name, email: member.email, role: member.role, status: member.status } : emptyMember(); editor.value = 'member'; dirty.value = false; message.value = ''; }
async function saveMember() { if (!selected.value) return; const id = selected.value.id; const result = editedMember.value ? await tenants.updateMember(context(), id, editedMember.value.id, plain(memberDraft.value), editedMember.value.revision) : await tenants.inviteMember(context(), id, plain(memberDraft.value)); if ('error' in result) { message.value = result.error.message; return; } editor.value = null; dirty.value = false; revision.value++; message.value = editedMember.value ? '成员信息已保存' : '已添加 Mock 成员，未发送真实邀请'; await open(id, 'members', true, true); }
async function removeMember(member: Member) { if (!selected.value || !window.confirm(`移除 ${member.name}？此操作会取消其演示访问权限。`)) return; const id = selected.value.id, result = await tenants.removeMember(context(), id, member.id, member.revision); if ('error' in result) { message.value = result.error.message; return; } revision.value++; message.value = '成员已移除'; await open(id, 'members', true, true); }
function startQuota() { if (!selected.value) return; quotaDraft.value = plain(selected.value.quota); quotaPreview.value = null; editor.value = 'quota'; dirty.value = false; message.value = ''; }
async function previewQuota() { if (!selected.value) return; const result = await tenants.previewQuota(context(), selected.value.id, plain(quotaDraft.value)); if ('error' in result) { message.value = result.error.message; return; } quotaPreview.value = result.data; message.value = '已预览配额影响'; }
async function saveQuota() { if (!selected.value) return; const id = selected.value.id, result = await tenants.updateQuota(context(), id, plain(quotaDraft.value), selected.value.revision); if ('error' in result) { message.value = result.error.message; return; } editor.value = null; dirty.value = false; quotaPreview.value = null; revision.value++; message.value = '配额已更新'; await open(id, 'quotas', true, true); }
function setQuota(resource: QuotaResource, key: 'limit' | 'warningAt', value: number, tenant = false) { const target = tenant ? tenantDraft.value.quota : quotaDraft.value; target[resource][key] = value; if (!tenant) quotaPreview.value = null; dirty.value = true; }
useUnsavedChanges(() => dirty.value);
</script>
<template>
<div class="atlas-dashboard atlas-tenants">
<main class="atlas-workspace"><header class="atlas-header"><div><small>IoT Atlas / 租户管理</small><h1>租户管理</h1><p>查看租户隔离、成员角色和资源配额。</p></div><div class="header-actions"><label>当前租户<select aria-label="当前租户" :value="currentTenant" :disabled="role !== 'platformAdmin'" @change="switchTenant(($event.target as HTMLSelectElement).value)"><option value="all">全部租户</option><option v-for="item in choices" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>主题<select aria-label="主题" v-model="themeChoice"><option value="dark">暗色</option><option value="light">亮色</option><option value="system">跟随系统</option></select></label><label>演示身份<select aria-label="演示身份" :value="role" @change="changeRole(($event.target as HTMLSelectElement).value as Role)"><option value="platformAdmin">平台管理员</option><option value="tenantAdmin">租户管理员</option><option value="operator">运维工程师</option><option value="viewer">数据观察员</option></select></label></div></header>
<div class="tenant-context" role="status">当前上下文：{{ names[currentTenant] ?? selected?.name ?? currentTenant }} · 配额健康：<strong :class="['tenant-health', selectedHealth]">{{ healthNames[selectedHealth] }}</strong>。切换租户后列表和大盘按该租户查询。<details class="scenario-control"><summary>Mock 场景</summary><label>服务状态<select aria-label="租户 Mock 场景" v-model="scenario"><option value="normal">正常</option><option value="slow">缓慢</option><option value="offline">服务离线</option><option value="forbidden">无权限</option></select></label></details></div>
<p v-if="message" class="tenant-feedback" role="status">{{ message }}</p>
<div class="tenant-layout"><div><ElCard class="tenant-panel"><div class="tenant-toolbar"><label>搜索租户<input aria-label="搜索租户" v-model="draft.keyword"></label><label>套餐<select aria-label="租户套餐" :value="draft.plan ?? ''" @change="draft.plan = (($event.target as HTMLSelectElement).value || undefined) as TenantQuery['plan']"><option value="">全部</option><option v-for="(value, key) in planNames" :key="key" :value="key">{{ value }}</option></select></label><label>状态<select aria-label="租户状态" :value="draft.status ?? ''" @change="draft.status = (($event.target as HTMLSelectElement).value || undefined) as TenantQuery['status']"><option value="">全部</option><option v-for="(value, key) in statusNames" :key="key" :value="key">{{ value }}</option></select></label><label>配额健康<select aria-label="配额健康" :value="draft.health ?? ''" @change="draft.health = (($event.target as HTMLSelectElement).value || undefined) as TenantQuery['health']"><option value="">全部</option><option v-for="(value, key) in healthNames" :key="key" :value="key">{{ value }}</option></select></label><ElButton type="primary" @click="query = { ...draft, page: 1 }">查询</ElButton><ElButton v-if="canWrite" type="primary" @click="selected = null; startTenant('new')">新建租户</ElButton></div></ElCard><ElCard class="tenant-panel"><h2>租户列表 · 共 {{ total }} 条</h2><div class="tenant-table"><table><thead><tr><th>名称</th><th>标识</th><th>套餐</th><th>设备</th><th>成员</th><th>消息量</th><th>配额健康 / 最高使用率</th><th>状态</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><button @click="open(row.id)">{{ row.name }}</button></td><td>{{ row.key }}</td><td>{{ planNames[row.plan] }}</td><td>{{ row.usage.find(item => item.resource === 'devices')?.used }}/{{ row.quota.devices.limit }}</td><td>{{ row.memberCount }}</td><td>{{ row.usage.find(item => item.resource === 'messages')?.used }}</td><td><span :class="['tenant-health', row.health]">{{ healthNames[row.health] }}</span> · {{ Math.max(...row.usage.map(item => item.percent)) }}%</td><td>{{ statusNames[row.status] }}</td></tr></tbody></table><p v-if="!rows.length">当前条件没有可访问的租户。</p></div><div class="tenant-actions"><ElButton :disabled="query.page <= 1" @click="query = { ...query, page: query.page - 1 }">上一页</ElButton><span>{{ query.page }} / {{ Math.max(1, Math.ceil(total / query.pageSize)) }}</span><ElButton :disabled="query.page * query.pageSize >= total" @click="query = { ...query, page: query.page + 1 }">下一页</ElButton></div></ElCard></div>
<div><ElCard v-if="selected" class="tenant-panel"><div class="tenant-detail-head"><div><h2>{{ selected.name }} · {{ statusNames[selected.status] }}</h2><p>{{ selected.key }} · {{ planNames[selected.plan] }} · {{ selected.email }}</p></div><ElButton @click="selected = null">关闭</ElButton></div><nav class="tenant-tabs" aria-label="租户详情页签"><button v-for="(label, id) in tabs" :key="id" :aria-current="tab === id ? 'page' : undefined" @click="checkDiscard() && (tab = id, editor = null, dirty = false)">{{ label }}</button></nav>
<div v-if="tab === 'overview'"><div class="tenant-facts"><span>联系人</span><strong>{{ selected.contact }}</strong><span>创建时间</span><strong>{{ new Date(selected.createdAt).toLocaleString('zh-CN') }}</strong><span>成员</span><strong>{{ selected.memberCount }} 人</strong><span>设备配额</span><strong>{{ selected.usage[0].used }}/{{ selected.quota.devices.limit }}</strong></div><p>{{ selected.description }}</p><ElButton v-if="canWrite" @click="startTenant('edit')">编辑租户</ElButton></div>
<div v-if="tab === 'members'"><div class="tenant-actions"><h3>成员管理</h3><ElButton v-if="canWrite" type="primary" @click="startMember(null)">添加成员</ElButton></div><div class="tenant-table"><table><thead><tr><th>姓名</th><th>邮箱</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="member in selected.members" :key="member.id"><td>{{ member.name }}</td><td>{{ member.email }}</td><td>{{ roleNames[member.role] }}</td><td>{{ member.status === 'active' ? '启用' : '停用' }}</td><td><template v-if="canWrite"><ElButton @click="startMember(member)">编辑</ElButton><ElButton @click="removeMember(member)">移除</ElButton></template><span v-else>只读</span></td></tr></tbody></table></div></div>
<div v-if="tab === 'roles'"><h3>角色与权限预览</h3><div class="tenant-table"><table><thead><tr><th>角色</th><th>能力</th><th>管理租户</th></tr></thead><tbody><tr v-for="(capabilities, key) in memberPermissions" :key="key"><td>{{ roleNames[key] }}</td><td>{{ capabilities.join('、') }}</td><td>只读</td></tr></tbody></table></div><p>权限预览为只读；操作仍由各端 Mock 服务检查角色与租户。</p></div>
<div v-if="tab === 'quotas'"><div class="tenant-actions"><h3>资源配额</h3><ElButton v-if="canWrite" type="primary" @click="startQuota">编辑配额</ElButton></div><div class="tenant-quota-grid"><div v-for="row in selected.usage" :key="row.resource" class="tenant-quota"><div><strong>{{ resourceNames[row.resource] }}</strong><span :class="['tenant-health', row.health]">{{ healthNames[row.health] }}</span></div><p>{{ row.used }} / {{ row.limit }} · {{ row.percent }}%</p><progress :value="Math.min(100, row.percent)" max="100" :aria-label="`${resourceNames[row.resource]}配额使用率`"></progress><small>预警阈值 {{ row.warningAt }}%</small></div></div></div>
<div v-if="tab === 'products'"><h3>关联产品</h3><p>本租户已用 {{ selected.usage.find(item => item.resource === 'products')?.used }} 个产品名额。</p><RouterLink :to="`/products?tenant=${encodeURIComponent(selected.id)}`">查看产品列表</RouterLink></div>
<div v-if="tab === 'devices'"><h3>关联设备</h3><p>本租户已用 {{ selected.usage.find(item => item.resource === 'devices')?.used }} 个设备名额。</p><RouterLink :to="`/devices?tenant=${encodeURIComponent(selected.id)}`">查看设备列表</RouterLink></div></ElCard></div></div></main>
<div v-if="editor" class="tenant-modal-backdrop"><section class="tenant-modal" role="dialog" aria-modal="true" :aria-label="editor === 'tenant' ? '编辑租户' : editor === 'member' ? '编辑成员' : '编辑配额'"><div class="tenant-detail-head"><h2>{{ editor === 'tenant' ? selected ? '编辑租户' : '新建租户' : editor === 'member' ? editedMember ? '编辑成员' : '添加成员' : '编辑配额' }}</h2><button aria-label="关闭编辑" @click="closeEditor">×</button></div><p v-if="message" class="tenant-feedback" role="status">{{ message }}</p>
<div v-if="editor === 'tenant'" class="tenant-form"><label>租户名称<input aria-label="租户名称" v-model="tenantDraft.name" @input="dirty = true"></label><label>租户标识<input aria-label="租户标识" v-model="tenantDraft.key" @input="dirty = true"></label><label>套餐<select aria-label="编辑套餐" v-model="tenantDraft.plan" @change="dirty = true"><option v-for="(value, key) in planNames" :key="key" :value="key">{{ value }}</option></select></label><label>状态<select aria-label="编辑租户状态" v-model="tenantDraft.status" @change="dirty = true"><option v-for="(value, key) in statusNames" :key="key" :value="key">{{ value }}</option></select></label><label>联系人<input aria-label="联系人" v-model="tenantDraft.contact" @input="dirty = true"></label><label>联系邮箱<input aria-label="联系邮箱" type="email" v-model="tenantDraft.email" @input="dirty = true"></label><label class="wide">描述<textarea aria-label="租户描述" v-model="tenantDraft.description" @input="dirty = true"></textarea></label><div class="tenant-quota-edit wide"><h3>资源上限与预警</h3><div v-for="resource in resources" :key="resource"><strong>{{ resourceNames[resource] }}</strong><label>硬上限<input :aria-label="`租户${resourceNames[resource]}上限`" type="number" min="1" :value="tenantDraft.quota[resource].limit" @input="setQuota(resource, 'limit', Number(($event.target as HTMLInputElement).value), true)"></label><label>预警百分比<input :aria-label="`租户${resourceNames[resource]}预警`" type="number" min="1" max="100" :value="tenantDraft.quota[resource].warningAt" @input="setQuota(resource, 'warningAt', Number(($event.target as HTMLInputElement).value), true)"></label></div></div><div class="tenant-actions wide"><ElButton type="primary" @click="saveTenant">保存租户</ElButton><ElButton @click="closeEditor">取消</ElButton></div></div>
<div v-if="editor === 'member'" class="tenant-form"><label>成员姓名<input aria-label="成员姓名" v-model="memberDraft.name" @input="dirty = true"></label><label>成员邮箱<input aria-label="成员邮箱" type="email" v-model="memberDraft.email" @input="dirty = true"></label><label>成员角色<select aria-label="成员角色" v-model="memberDraft.role" @change="dirty = true"><option v-for="(value, key) in roleNames" :key="key" :value="key">{{ value }}</option></select></label><label v-if="editedMember">成员状态<select aria-label="成员状态" v-model="memberDraft.status" @change="dirty = true"><option value="active">启用</option><option value="disabled">停用</option></select></label><p class="wide">权限预览：{{ memberPermissions[memberDraft.role].join('、') }}。邀请仅在当前浏览器创建 Mock 成员，不发送邮件。</p><div class="tenant-actions wide"><ElButton type="primary" @click="saveMember">确认保存</ElButton><ElButton @click="closeEditor">取消</ElButton></div></div>
<div v-if="editor === 'quota'"><div class="tenant-quota-edit"><div v-for="resource in resources" :key="resource"><strong>{{ resourceNames[resource] }}</strong><label>硬上限<input :aria-label="`${resourceNames[resource]}上限`" type="number" min="1" :value="quotaDraft[resource].limit" @input="setQuota(resource, 'limit', Number(($event.target as HTMLInputElement).value))"></label><label>预警百分比<input :aria-label="`${resourceNames[resource]}预警`" type="number" min="1" max="100" :value="quotaDraft[resource].warningAt" @input="setQuota(resource, 'warningAt', Number(($event.target as HTMLInputElement).value))"></label></div></div><p v-if="quotaPreview" :role="quotaPreview.blocked.length ? 'alert' : 'status'">影响预览：{{ quotaPreview.blocked.length ? `新上限低于已用量：${quotaPreview.blocked.map(row => `${resourceNames[row.resource]} ${row.used}/${row.limit}`).join('、')}` : '当前已用量均未超过新上限；达到硬上限后将拒绝创建。' }}</p><nav v-if="quotaPreview?.blocked.length" class="tenant-quota-help" aria-label="配额资源处理入口"><p>可提高当前上限，或前往对应资源页处理占用。</p><template v-for="row in quotaPreview.blocked" :key="row.resource"><RouterLink v-if="quotaResourceHref(row.resource, selected?.id ?? '')" :to="quotaResourceHref(row.resource, selected?.id ?? '')!">前往{{ resourceNames[row.resource] }}处理占用</RouterLink><span v-else>{{ resourceNames[row.resource] }}当前不提供清理操作，请提高上限。</span></template></nav><div class="tenant-actions"><ElButton @click="previewQuota">预览影响</ElButton><ElButton type="primary" :disabled="!quotaPreview || quotaPreview.blocked.length > 0" @click="saveQuota">保存配额</ElButton><ElButton @click="closeEditor">取消</ElButton></div></div>
</section></div></div>
</template>
